import {normalizeSearch,contactLinks,phoneNumber,featured,pageListings,deletionEligibility,validate,millis} from './model.js';
import {listingImageData} from '../livestock-images.js';
import {selectAds,PLACEMENTS} from '../commercial-model.js';
import {accessModel,can} from '../admin-permissions.js';
if(!environmentAllowed(runtimeConfig,location)){document.getElementById('app').textContent='MELKAK — التشغيل محظور في هذه البيئة؛ Production غير جاهز.';throw Error('MELKAK environment blocked');}
const legacy=await (await fetch('./melkak/legacy-countries.json')).json(),countries=countryConfig(legacy),store=createDatasource(runtimeConfig,countries);
// Keep sample Hero requests pending so the initial preview shows the default six-country banner.
store.state.ads.filter(a=>a.placement==='hero').forEach(a=>a.status='pending');
const s={lang:localStorage.getItem('melkak.lang')==='en'?'en':'ar',country:'AE',city:'',category:'',search:'',min:'',max:'',sort:'newest',attributes:{},page:1,role:'user',signedIn:true,hero:0,gallery:{},favorites:new Set(),step:0,draft:null,editing:null,error:'',busy:false,adminCountry:'AE',adminStatus:'',unread:new Set()};
const $=q=>document.querySelector(q),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),t=(ar,en)=>s.lang==='en'?en:ar,label=a=>a[s.lang==='en'?1:0];
function actor(){if(!s.signedIn)return {uid:null,role:null,permissions:[],name:t('زائر','Guest')};const uid=s.role==='assistant'?'demo-assistant':'demo-owner';const access=accessModel(uid,s.role==='super_admin'?{admin:true}:{},{status:'active'},s.role==='assistant'?{role:'admin_assistant',adminStatus:'active',permissions:['dashboard_view','listings_view','reports_view']}:null,{enabled:true,superAdminUids:['demo-owner']});return {...access,name:s.role==='assistant'?t('مساعد تجريبي','Demo assistant'):t('سامي','Sami')};}
const price=a=>new Intl.NumberFormat(s.lang==='ar'?'ar-AE':'en',{maximumFractionDigits:['OMR','JOD'].includes(countries[a.country]?.currency)?3:2}).format(a.price)+` <small>${countries[a.country]?.currency||''}</small>`;
const date=v=>new Intl.DateTimeFormat(s.lang==='ar'?'ar-AE':'en',{dateStyle:'medium'}).format(new Date(v||Date.now()));
const age=v=>{const hours=Math.max(0,Math.floor((Date.now()-v)/3600000));return hours<24?t(`منذ ${hours||1} س`,`${hours||1}h ago`):t(`منذ ${Math.floor(hours/24)} ي`,`${Math.floor(hours/24)}d ago`);};
const asset=src=>/^\.\/melkak\/assets\/[a-z-]+\.(?:svg|webp)$/.test(src)||/^data:image\/jpeg;base64,[A-Za-z0-9+/]+={0,2}$/.test(src)?src:'./melkak/assets/other.svg';
const button=(text,action,extra='',cls='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const link=(text,hash,cls='')=>`<a class="${cls}" href="#/${esc(hash)}">${text}</a>`;
function option(value,text,selected){return `<option value="${esc(value)}" ${selected===value?'selected':''}>${esc(text)}</option>`;}
function countryOptions(selected,all=false){return (all?option('',t('كل الدول','All countries'),selected):'')+Object.entries(countries).map(([id,c])=>option(id,s.lang==='en'?c.english:c.name,selected)).join('');}
function cityOptions(country,selected,all=true){return (all?option('',t('كل المدن','All cities'),selected):'')+Object.entries(countries[country].regions).map(([region,cities])=>`<optgroup label="${esc(region)}">${cities.map(c=>option(c,c,selected)).join('')}</optgroup>`).join('');}
function categoryOptions(value,all=false){return (all?option('',t('كل الأقسام','All categories'),value):'')+store.state.categories.filter(c=>c.enabled).sort((a,b)=>a.order-b.order).map(c=>option(c.id,label(c.name),value)).join('');}
const noData=text=>`<div class="empty">${icon('grid')}<p>${text||t('لا توجد إعلانات مطابقة حاليًا','No matching listings yet')}</p></div>`;
function toast(text){$('#toast').textContent=text;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').textContent='',5000);}
function errorText(e){const map={DURATION:['اختر مدة صحيحة من 1 إلى 365 يومًا وتواريخ صالحة','Choose 1–365 days and valid dates'],CATEGORY:['اختر قسمًا متاحًا','Choose an available category'],LOCATION:['اختر دولة ومنطقة ومدينة صحيحة','Choose a valid country, region and city'],DETAILS:['أدخل عنوانًا من 3–100 حرف ووصفًا من 10–2000 حرف','Enter a 3–100 character title and 10–2000 character description'],PRICE:['أدخل سعرًا صحيحًا','Enter a valid price'],IMAGES:['اختر من صورة إلى 3 صور JPEG مضغوطة وغير مكررة','Choose 1–3 unique compressed JPEG images'],CONSENT:['أدخل رقمًا صحيحًا، اختر وسيلة تواصل ووافق على استخدامه في الإعلان','Enter a valid number, enable contact and explicitly consent'],FIELDS:['تحقق من حقول القسم','Check category fields'],OWNER:['يمكنك إدارة إعلاناتك فقط','You can only manage your listings'],PERMISSION:['لا تملك الصلاحية لهذا الإجراء','You do not have permission'],HISTORY:['توجد سجلات مرتبطة. استخدم إخفاء الإعلان بدل الحذف','Linked history exists. Hide this listing instead'],LEGACY:['هذا إعلان قديم محفوظ. إخفاؤه متاح؛ تحرير بياناته يحتاج مرحلة توافق مستقلة','Legacy listing preserved. Hide is available; editing needs a separate compatibility phase'],MODERATED:['الإعلان مقفل للمراجعة','Listing locked for review'],STATE:['الإجراء غير متاح في الحالة الحالية','Action unavailable in this state'],REASON:['اكتب السبب أولًا','Enter a reason'],DUPLICATE:['يوجد طلب معلق بالفعل','A pending request already exists'],TOO_MANY_IMAGES:['الحد الأقصى 3 صور','Maximum 3 images'],INVALID_IMAGE:['اختر JPG أو PNG أو WebP فقط','Choose JPG, PNG or WebP'],IMAGE_TOO_LARGE:['الملف كبير جدًا. الحد 30 MB قبل الضغط','File exceeds the 30 MB input limit'],IMAGES_TOO_LARGE:['حجم الصور كبير بعد الضغط','Compressed images are too large']};return label(map[e.code||e.message]||[e.message==='AUTH'?'سجل الدخول أولًا':'تعذر إكمال الإجراء المحلي. تحقق من البيانات.','Could not complete the local action. Check the input.']);}
function favoritesLoad(){try{s.favorites=new Set(JSON.parse(localStorage.getItem('melkak.favorites.'+actor().uid)||'[]'));}catch{s.favorites=new Set();}}favoritesLoad();
function brand(){return `<a class="brand" href="#/home"><img src="./melkak/assets/logo.svg" alt="MELKAK"><span><strong>${t('مِلكك','MELKAK')}</strong><small>${t('MELKAK · بيع واشتري مباشرة','Buy and sell directly')}</small></span></a>`;}
function notifications(){return [...(can(actor(),'reports_view')?store.state.reports.filter(r=>r.status==='open').map(r=>({...r,section:'reports',text:t('بلاغ جديد','New report')})):[]),...(can(actor(),'services_view')?store.state.services.filter(r=>r.status==='pending').map(r=>({...r,section:'featured',text:t('طلب خدمة إعلان','Listing service request')})):[])].slice(0,20);}
function shell(content,route){const admin=actor().role;return `<div class="preview"><div class="wrap"><span>${t('معاينة تجريبية — البيانات المعروضة غير حقيقية','Demo preview — fictional data')}</span><label>${t('تجربة','Preview')}<select id="preview-role" aria-label="${t('دور المعاينة المحلية','Local preview role')}">${option('user',t('مستخدم','User'),s.role)}${option('super_admin','Super Admin',s.role)}${option('assistant',t('مساعد مدير','Assistant'),s.role)}</select></label></div></div>
<header class="topbar"><div class="wrap">${brand()}<div class="top-location">${icon('pin')}<div><select data-country aria-label="${t('الدولة الحالية','Current country')}">${countryOptions(s.country)}</select><select data-city aria-label="${t('المدينة الحالية','Current city')}">${cityOptions(s.country,s.city)}</select></div></div><div class="header-actions">${button(s.lang==='ar'?'English':'العربية','language','','language')}${button(icon('bell')+(notifications().filter(n=>!s.unread.has(n.id)).length?`<span>${notifications().filter(n=>!s.unread.has(n.id)).length}</span>`:''),'notifications',`aria-label="${t('الإشعارات','Notifications')}"`,'icon-button')}${link(icon('user')+t(s.signedIn?'حسابي':'تسجيل الدخول',s.signedIn?'My account':'Sign in'),'account','button account-link')}${link(icon('plus')+t('أضف إعلانك','Post an ad'),'add','button primary add-desktop')}</div></div><nav class="navline wrap" aria-label="${t('التنقل الرئيسي','Main navigation')}">${link(t('الرئيسية','Home'),'home',route==='home'?'active':'')}${link(t('تصفح الأقسام','Browse categories'),'categories')}${link(t('جميع الإعلانات','All listings'),'market')}${link(t('إعلانات مميزة','Featured listings'),'featured')}${link(t('تواصل معنا','Contact us'),'contact')}${link(t('من نحن','About us'),'about')}${link(t('المفضلة','Favorites'),'favorites')}${admin?link(t('لوحة الإدارة','Dashboard'),'admin'):''}<span class="note">${t('مجاني حاليًا · تواصل مباشر · بدون عمولة','Currently free · Direct contact · No commission')}</span></nav></header><div class="mobile-location mobile-only">${icon('pin')}<select data-country aria-label="${t('دولة السوق','Market country')}">${countryOptions(s.country)}</select><select data-city aria-label="${t('مدينة السوق','Market city')}">${cityOptions(s.country,s.city)}</select></div>
<main id="main" class="wrap app-page" tabindex="-1">${content}</main><footer class="site-footer"><div class="wrap">${brand()}<p>${t('بيع واشتري مباشرة','Buy and sell directly')}</p><nav aria-label="${t('روابط الموقع','Footer links')}">${[['about','من نحن','About us'],['contact','تواصل معنا','Contact us'],['privacy','سياسة الخصوصية','Privacy'],['terms','الشروط','Terms']].map(([r,ar,en])=>link(t(ar,en),r)).join('')}</nav><small>© ${new Date().getFullYear()} MELKAK</small></div></footer><nav class="bottom-nav" aria-label="${t('تنقل الهاتف','Mobile navigation')}">${[['home','home','الرئيسية','Home'],['categories','grid','الأقسام','Categories'],['add','plus','أضف إعلان','Post ad'],['favorites','heart','المفضلة','Favorites'],['account','user','حسابي','Account']].map(([r,i,ar,en])=>link(icon(i)+t(ar,en),r,`${r==='add'?'add ':''}${route===r?'active':''}`)).join('')}</nav>`;}
function searchbar(){return `<form id="search-form" class="searchbar">${icon('search')}<input name="search" aria-label="${t('ابحث عن أي شيء','Search anything')}" placeholder="${t('ابحث عن ما تريد...','Search for what you want...')}" value="${esc(s.search)}"><select name="country" aria-label="${t('دولة البحث','Search country')}">${countryOptions(s.country)}</select><select name="city" aria-label="${t('مدينة البحث','Search city')}">${cityOptions(s.country,s.city)}</select><select name="category" aria-label="${t('قسم البحث','Search category')}">${categoryOptions(s.category,true)}</select>${button(icon('grid')+t('الفلاتر','Filters'),'filter-drawer','aria-haspopup="dialog"','filter-toggle')}<button class="primary" type="submit">${t('بحث','Search')}</button></form>`;}
function categories(large=false){return `<div class="categories ${large?'category-grid-large':''}">${store.state.categories.filter(c=>c.enabled).sort((a,b)=>a.order-b.order).map(c=>link(`<span class="cat-icon">${icon(c.icon)}</span><span>${esc(label(c.name))}</span>`,'market/'+c.id,'category'+(c.featured?' category-featured':'' ))).join('')}</div>`;}
function contacts(a,compact=false){const c=contactLinks(a,countries);return `${c.call?`<a class="button primary" href="${esc(c.call)}" data-contact="call" data-id="${esc(a.id)}">${icon('call')}${t('اتصال','Call')}</a>`:button(t('اتصال غير متاح','Call unavailable'),'none','disabled')}${c.whatsapp?`<a class="button" href="${esc(c.whatsapp)}" target="_blank" rel="noopener noreferrer" data-contact="whatsapp" data-id="${esc(a.id)}">${icon('call')}${t('واتساب','WhatsApp')}</a>`:button(t('واتساب غير متاح','WhatsApp unavailable'),'none','disabled')}${!compact&&c.text?`<p dir="ltr">${esc(c.text)}</p>`:''}`;}
function card(a){return `<article class="listing ${featured(a)?'featured':''}" data-listing="${esc(a.id)}"><div class="listing-photo"><a href="#/listing/${encodeURIComponent(a.id)}"><img data-card-src="${asset(a.images[0])}" alt="${esc(a.title)}" loading="lazy" width="320" height="210"></a>${button(icon('heart'),'favorite',`data-id="${esc(a.id)}" aria-label="${t('حفظ في المفضلة','Save favorite')}" aria-pressed="${s.favorites.has(a.id)}"`,'favorite')}${featured(a)?`<span class="badge">⭐ ${t('مميز','Featured')}</span>`:''}<span class="photo-count">▧ ${a.images.length}</span></div><div class="listing-body"><h3>${link(esc(s.lang==='en'?a.titleEn||a.title:a.title),'listing/'+a.id)}</h3><div class="meta">${icon('pin')}<span>${esc(a.city)} · ${esc(s.lang==='en'?countries[a.country].english:countries[a.country].name)}</span><time datetime="${new Date(a.createdAt).toISOString()}">${age(a.createdAt)}</time></div><div class="price">${price(a)}</div><div class="card-actions">${contacts(a,true)}${link(t('عرض التفاصيل','View details'),'listing/'+a.id,'details-link')}</div></div></article>`;}
function cards(items){return `<div class="cards">${items.length?items.map(card).join(''):noData()}</div>`;}
function publicRows(){return store.state.listings.filter(a=>store.state.categories.some(c=>c.id===a.category&&c.enabled));}
function filters(){const c=CATEGORIES.find(c=>c.id===s.category);return `<form id="filters-form"><div class="filters"><label>${t('المدينة','City')}<select name="city">${cityOptions(s.country,s.city)}</select></label><label>${t('السعر من','Min price')}<input name="min" type="number" min="0" value="${esc(s.min)}"></label><label>${t('السعر إلى','Max price')}<input name="max" type="number" min="0" value="${esc(s.max)}"></label><label>${t('الترتيب','Sort')}<select name="sort">${option('newest',t('الأحدث','Newest'),s.sort)}${option('oldest',t('الأقدم','Oldest'),s.sort)}</select></label>${(c?.id==='livestock'?c.fields.filter(f=>['type','breed','gender'].includes(f.id)):(c?.fields||[]).slice(0,3)).map(f=>`<label>${esc(label(f.label))}${f.options.length?`<select name="attr:${f.id}">${option('',t('الكل','All'),s.attributes[f.id])}${f.options.map(o=>option(o[0],o[s.lang==='en'?2:1],s.attributes[f.id])).join('')}</select>`:`<input name="attr:${f.id}" value="${esc(s.attributes[f.id]||'')}">`}</label>`).join('')}</div><div class="manage-actions"><button type="submit" class="primary">${t('تطبيق الفلاتر','Apply filters')}</button>${button(t('مسح الفلاتر','Clear filters'),'clear-filters')}</div></form>`;}
function market(category){if(s.category!==(category||''))s.attributes={};s.category=category||'';const cat=CATEGORIES.find(c=>c.id===s.category);const data=pageListings(publicRows(),s,countries,s.page);return `<div class="breadcrumb">${link(t('الرئيسية','Home'),'home')} / ${t('الإعلانات','Listings')}</div><div class="page-head"><div><h1>${cat?esc(label(cat.name)):t('جميع الإعلانات','All listings')}</h1><p class="muted small">${data.total} ${t('إعلان محلي مطابق','matching local listings')}</p></div>${link(icon('plus')+t('أضف إعلان','Post an ad'),'add','button primary')}</div>${searchbar()}<div class="panel"><details class="advanced-filters" ${matchMedia('(min-width:801px)').matches?'open':''}><summary>${t('فلاتر القسم والسعر','Category and price filters')}</summary>${filters()}</details></div>${cards(data.items)}<div class="load-more">${s.page>1?button(t('الصفحة السابقة','Previous page'),'page-prev'):''}${data.hasMore?button(t('الصفحة التالية','Next page'),'page-next'):''}</div>`;}
function details(id){const a=store.state.listings.find(x=>x.id===id);if(!a||a.status!=='active'||a.saleType==='auction')return noData(t('الإعلان غير متاح في السوق','Listing unavailable in the market'));const i=s.gallery[id]||0,c=CATEGORIES.find(c=>c.id===a.category),similar=store.state.listings.filter(x=>x.id!==id&&x.category===a.category&&x.country===a.country&&x.status==='active'&&x.saleType!=='auction').slice(0,4);return `<div class="breadcrumb">${link(t('الرئيسية','Home'),'home')} / ${link(esc(label(c.name)),'market/'+c.id)}</div><div class="page-head"><h2>${t('تفاصيل الإعلان','Listing details')}</h2>${button(icon('heart')+t('المفضلة','Favorite'),'favorite',`data-id="${esc(id)}" aria-pressed="${s.favorites.has(id)}"`)}</div><div class="detail-layout"><div><div class="detail-stage"><img src="${asset(a.images[i])}" alt="${esc(a.title)}" width="720" height="500"><span class="photo-count" dir="ltr" aria-live="polite">${i+1} / ${a.images.length}</span>${featured(a)?`<span class="badge">★ ${t('إعلان مميز','Featured listing')}</span>`:''}</div><div class="thumbs">${a.images.map((image,index)=>index===i?'':button(`<img src="${asset(image)}" alt="">`,'gallery',`data-id="${esc(id)}" data-index="${index}" aria-label="${t('عرض الصورة','Show image')} ${index+1}"`)).join('')}</div><div class="panel"><h2>${t('تفاصيل القسم','Specifications')}</h2><div class="attributes">${c.fields.filter(f=>a.attributes[f.id]).map(f=>`<div><span class="muted">${esc(label(f.label))}</span><strong>${esc(f.options.find(o=>o[0]===a.attributes[f.id])?.[s.lang==='en'?2:1]||a.attributes[f.id])}</strong></div>`).join('')}</div></div><div class="panel"><h2>${t('الوصف','Description')}</h2><p>${esc(a.description)}</p></div></div><aside class="panel detail-info"><span class="status-tag">${esc(label(c.name))}</span><h1>${esc(s.lang==='en'?a.titleEn||a.title:a.title)}</h1><div class="price">${price(a)}</div><p class="muted">${esc(a.city)} · ${esc(s.lang==='en'?countries[a.country].english:countries[a.country].name)} · ${date(a.createdAt)}</p><div class="seller"><span class="avatar">${icon('user')}</span><div><strong>${esc(a.sellerName||t('البائع','Seller'))}</strong><p class="small muted">${t('تواصل مباشر مع صاحب الإعلان','Connect directly with the seller')}</p></div></div><div class="actions">${contacts(a)}${!a.contact?.consent?`<p class="notice">${t('لم يمنح صاحب هذا الإعلان القديم موافقة على نشر رقم التواصل.','The owner of this legacy listing has not consented to a public contact number.')}</p>`:''}</div><p class="notice">${t('عاين السلعة قبل الدفع. لا تشارك رموز التحقق مع أي شخص.','Inspect the item before paying. Never share verification codes.')}</p>${button(icon('flag')+t('الإبلاغ عن الإعلان','Report listing'),'report',`data-id="${esc(id)}"`,'danger')}${button(t('الإبلاغ عن المستخدم','Report user'),'report-user',`data-id="${esc(a.ownerUid)}"`,'text-link')}</aside></div><div class="section-head"><h2>${t('إعلانات مشابهة','Similar listings')}</h2></div>${cards(similar)}`;}
const steps=[['الدولة','Country'],['المدينة','City'],['القسم','Category'],['الصور','Photos'],['التفاصيل','Details'],['التواصل','Contact'],['المراجعة والنشر','Review & publish']];
function newDraft(){const c=countries[s.country],region=Object.keys(c.regions).find(r=>c.regions[r].includes(s.city))||Object.keys(c.regions)[0];return {country:s.country,region,city:s.city||c.regions[region][0],category:store.state.categories.find(c=>c.enabled)?.id||'livestock',title:'',description:'',price:'',images:[],attributes:{},contact:{phone:'',consent:false,call:true,whatsapp:true,showNumber:false}};}
function fieldHTML(f,d){return `<label>${esc(label(f.label))}${f.options.length?`<select name="attr:${f.id}"><option value="">${t('اختر','Choose')}</option>${f.options.map(o=>option(o[0],o[s.lang==='en'?2:1],d.attributes[f.id]||'')).join('')}</select>`:`<input name="attr:${f.id}" type="${f.type}" ${f.type==='number'?'min="0"':''} maxlength="300" value="${esc(d.attributes[f.id]||'')}">`}</label>`;}
function locationFields(d){return `<label>${t('الدولة','Country')}<select name="country" data-draft-country>${countryOptions(d.country)}</select></label><label>${t('المنطقة','Region')}<select name="region" data-draft-region>${Object.keys(countries[d.country].regions).map(r=>option(r,r,d.region)).join('')}</select></label><label>${t('المدينة','City')}<select name="city">${(countries[d.country].regions[d.region]||[]).map(c=>option(c,c,d.city)).join('')}</select></label>`;}
function detailsFields(d){const c=CATEGORIES.find(x=>x.id===d.category);return `<label class="full">${t('عنوان الإعلان','Listing title')}<input name="title" required minlength="3" maxlength="100" value="${esc(d.title)}"></label><label>${t('السعر','Price')} (${countries[d.country].currency})<input name="price" type="number" min="0" step="0.001" required value="${esc(d.price)}"></label>${c.fields.map(f=>fieldHTML(f,d)).join('')}<label class="full">${t('الوصف','Description')}<textarea name="description" minlength="10" maxlength="2000" required>${esc(d.description)}</textarea></label>`;}
function contactFields(d){return `<label class="full">${t('رقم التواصل لهذا الإعلان','Contact number for this listing')}<input name="phone" type="tel" dir="ltr" autocomplete="off" placeholder="+${countries[d.country].dial}…" value="${esc(d.contact?.phone||'')}"></label>${[['call','السماح بالاتصال','Allow calls'],['whatsapp','السماح بواتساب','Allow WhatsApp'],['showNumber','إظهار الرقم كنص','Show number as text']].map(([k,ar,en])=>`<label class="check"><input type="checkbox" name="${k}" ${d.contact?.[k]?'checked':''}>${t(ar,en)}</label>`).join('')}<label class="check full"><input type="checkbox" name="consent" ${d.contact?.consent?'checked':''}>${t('أوافق صراحة على استخدام هذا الرقم للتواصل العام بخصوص إعلاني.','I explicitly consent to this number being used for public contact about my listing.')}</label><p class="muted small full">${t('لن نستخدم رقم ملفك الشخصي تلقائيًا. عدم عرض الرقم كنص لا يخفيه عن روابط الاتصال وواتساب.','Your profile number is never used automatically. Hiding number text does not hide it from call or WhatsApp links.')}</p>`;}
function photoEditor(d,published=false){return `<div class="upload-zone image-manager" id="drop-zone" aria-label="${t('منطقة اختيار الصور','Photo upload area')}"><div class="image-manager-head"><strong>${t('صور الإعلان','Listing photos')}</strong><output class="image-manager-count" dir="ltr" aria-live="polite" aria-label="${t('عدد الصور، الحد الأقصى 3','Photo count, maximum 3')}">${d.images.length}/3</output></div><p class="muted small">JPG · PNG · WebP · ${t('حتى 3 صور — ضغط تلقائي مجاني','Up to 3 photos — free automatic compression')}</p>${button(icon('plus')+t('إضافة صور','Add photos'),'image-add',`${s.busy||d.images.length>=3?'disabled':''} aria-controls="photo-picker"`,'primary')}<input id="photo-picker" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden tabindex="-1" aria-label="${t('اختيار الصور من الجهاز','Choose photos from device')}" ${s.busy?'disabled':''}>${d.images.length>=3?`<small>${t('اكتمل العدد. يمكنك استبدال صورة أو حذفها لإضافة أخرى.','All slots filled. Replace or remove a photo to add another.')}</small>`:''}</div><div class="photo-editor">${d.images.map((src,i)=>`<div><img src="${asset(src)}" alt="${t('معاينة الصورة','Photo preview')} ${i+1}" width="240" height="170"><small>${i===0?t('الصورة الرئيسية','Main image'):t('صورة','Photo')+' '+(i+1)}</small><div class="buttons">${button(t('استبدال','Replace'),'image-replace',`data-index="${i}" ${s.busy?'disabled':''}`)}${button(t('حذف','Remove'),'image-remove',`data-index="${i}" ${s.busy||(published&&d.images.length===1)?'disabled':''}`,'danger')}${button(t('جعلها الرئيسية','Set main'),'image-main',`data-index="${i}" ${i===0||s.busy?'disabled':''}`)}${i>0?button('↑','image-up',`data-index="${i}" aria-label="${t('تقديم الصورة','Move photo earlier')}" ${s.busy?'disabled':''}`):''}</div></div>`).join('')}</div>${s.busy?`<p role="status">${t('جارٍ ضغط الصور…','Compressing photos…')}</p>`:''}`;}

function review(d){const c=CATEGORIES.find(x=>x.id===d.category);return `<div class="detail-layout"><img src="${asset(d.images[0])}" alt="${esc(d.title)}" width="320" height="230"><div><span class="status-tag">${esc(label(c.name))}</span><h2>${esc(d.title)}</h2><div class="price">${price(d)}</div><p>${esc(d.city)} · ${countries[d.country].currency}</p><p>${d.images.length} ${t('صور','photos')}</p><p dir="ltr">${esc(phoneNumber(d.contact.phone,d.country,countries))}</p></div></div><p class="notice">${t('سيُحفظ هذا الإعلان في الذاكرة المحلية للمعاينة فقط. لا يُنشر على الموقع الحقيقي.','This listing is saved in preview memory only. It will not be published to the live site.')}</p>`;}
function addListing(){if(!s.signedIn)return previewLogin();s.draft??=newDraft();const d=s.draft;let content='';if(s.step===0)content=`<div class="form-grid"><label>${t('أين تريد عرض إعلانك؟','Where will your listing appear?')}<select name="country" data-draft-country>${countryOptions(d.country)}</select></label></div>`;if(s.step===1)content=`<div class="form-grid">${locationFields(d)}</div>`;if(s.step===2)content=`<label>${t('اختر القسم المناسب','Choose a category')}<select name="category" data-draft-category>${categoryOptions(d.category)}</select></label><div class="chips">${CATEGORIES.map(c=>`<span class="status-tag">${esc(label(c.name))}</span>`).join('')}</div>`;if(s.step===3)content=photoEditor(d);if(s.step===4)content=`<div class="form-grid">${detailsFields(d)}</div>`;if(s.step===5)content=`<div class="form-grid">${contactFields(d)}</div>`;if(s.step===6)content=review(d);return `<div class="wizard"><div class="page-head"><div><div class="eyebrow">MELKAK</div><h1>${t('أضف إعلانك مجانًا','Post your ad for free')}</h1></div><span class="muted small">${s.step+1} / 7</span></div><div class="steps">${steps.map((a,i)=>`<div class="step ${i<=s.step?'active':''}" ${i===s.step?'aria-current="step"':''}>${i+1}. ${esc(label(a))}</div>`).join('')}</div><form id="wizard-form" class="panel" novalidate><h2>${esc(label(steps[s.step]))}</h2><p class="muted small">${t('خطوة بسيطة تقرّب إعلانك من المهتمين.','A simple step closer to the right buyer.')}</p><div class="section-head"></div>${content}${s.error?`<p role="alert" class="error">${esc(s.error)}</p>`:''}<div class="wizard-actions">${s.step>0?button(t('السابق','Back'),'wizard-back'):link(t('إلغاء','Cancel'),'home','button')}<button class="primary" type="submit" ${s.busy?'disabled':''}>${s.step===6?t('نشر الإعلان محليًا','Publish locally'):t('التالي','Continue')}${icon('arrow')}</button></div></form></div>`;}
function previewLogin(){return `<div class="panel"><h1>${t('جلسة المعاينة','Preview session')}</h1><p class="notice">${t('Google Auth الحقيقي محفوظ ولم تتغير جلسته. الدخول هنا لمحاكاة محلية فقط.','Real Google Auth is preserved and unchanged. This sign-in is for local simulation only.')}</p>${button(t('الدخول إلى جلسة المعاينة','Enter local preview'),'preview-login','','primary')}</div>`;}
function account(){if(!s.signedIn)return previewLogin();const a=actor();return `<div class="page-head"><h1>${t('حسابي','My account')}</h1><span class="status-tag">${t('جلسة معاينة محلية','Local preview session')}</span></div><div class="account-layout"><aside class="panel"><div class="seller"><span class="avatar">${icon('user')}</span><div><h2>${a.name}</h2><small>${a.role==='super_admin'?'Super Admin':a.role==='admin_assistant'?t('مساعد مدير','Assistant'):t('عضو مِلكك','MELKAK member')}</small></div></div><nav class="account-links">${[['profile','ملفي','Profile'],['my-listings','إعلاناتي','My listings'],['favorites','المفضلة','Favorites'],['contact-settings','بيانات التواصل','Contact details'],['location-settings','الدولة والمدينة','Location'],['settings','الإعدادات','Settings']].map(([r,ar,en])=>link(t(ar,en),r)).join('')}${button(t('تسجيل الخروج من المعاينة','Leave preview session'),'logout')}</nav></aside><div><div class="panel"><h2>${t('أهلًا بك في مِلكك','Welcome to MELKAK')}</h2><p class="muted">${t('إعلاناتك ومفضلاتك، في مكان واحد.','Your listings and favorites, all in one place.')}</p><div class="chips">${link(t('إدارة إعلاناتي','Manage my listings'),'my-listings','button')}${link(t('أضف إعلانًا','Post a listing'),'add','button')}</div></div><div class="panel"><h3>Google Auth</h3><p class="notice">${t('تسجيل Google والحسابات القديمة محفوظة بكودها الحالي. هذه جلسة محلية للمراجعة؛ لم تُربط ببياناتك الحقيقية.','Existing Google sign-in and legacy accounts are preserved. This local review session is not connected to your real data.')}</p>${a.role?link(t('فتح لوحة الإدارة','Open dashboard'),'admin','button primary'):''}</div></div></div>`;}
function myListings(){const all=store.state.listings.filter(a=>a.ownerUid===actor().uid&&a.saleType!=='auction'&&(!s.myStatus||a.status===s.myStatus)),items=all.slice((s.page-1)*PAGE_SIZE,s.page*PAGE_SIZE);return `<div class="page-head"><div><h1>${t('إعلاناتي','My listings')}</h1><p class="muted small">${all.length} ${t('إعلان محلي محفوظ','local listings')}</p></div>${link(icon('plus')+t('أضف إعلان','Post ad'),'add','button primary')}</div><div class="chips">${button(t('الكل','All'),'my-filter','data-status=""',!s.myStatus?'selected':'')}${Object.entries(STATUS).map(([key,n])=>button(label(n),'my-filter',`data-status="${key}"`,s.myStatus===key?'selected':'')).join('')}</div><div class="cards">${items.map(a=>`<article class="listing"><div class="listing-photo"><img src="${asset(a.images[0])}" alt="${esc(a.title)}" loading="lazy" width="320" height="210"></div><div class="listing-body"><span class="status-tag">${esc(label(STATUS[a.status]||STATUS.pending))}</span><h3>${esc(a.title)}</h3><div class="price">${price(a)}</div><p class="muted small">${esc(a.city)}</p>${link(t('إدارة الإعلان','Manage listing'),'manage/'+a.id,'button')}</div></article>`).join('')||noData()}</div><div class="load-more">${s.page>1?button(t('السابق','Previous'),'page-prev'):''}${s.page*PAGE_SIZE<all.length?button(t('التالي','Next'),'page-next'):''}</div>`;}
function manage(id){const a=store.state.listings.find(x=>x.id===id);if(!a||a.ownerUid!==actor().uid)return noData(t('لا يمكنك إدارة هذا الإعلان','You cannot manage this listing'));if(s.editing!==id){s.editing=id;s.draft=structuredClone(a);}const d=s.draft;return `<div class="page-head"><div><div class="breadcrumb">${link(t('إعلاناتي','My listings'),'my-listings')} / ${t('إدارة الإعلان','Manage listing')}</div><h1>${esc(a.title)}</h1></div><span class="status-tag">${esc(label(STATUS[a.status]||STATUS.pending))}</span></div>${a.legacy?`<div class="notice">${t('إعلان قديم محفوظ. إخفاؤه متاح، ولا يُحذف نهائيًا ولا تُعدّل بياناته الأصلية.','Preserved legacy listing. It can be hidden; original data cannot be edited or permanently deleted.')}</div>`:''}<form id="manage-form" data-id="${esc(id)}"><div class="manage-layout"><div class="panel"><h2>${t('الصور','Photos')}</h2>${a.legacy?`<img src="${asset(a.images[0])}" alt="${esc(a.title)}" width="280" height="200">`:photoEditor(d,a.status==='active')}<p class="muted small">${t('لا يمكن حذف آخر صورة لإعلان منشور.','The last photo of a published listing cannot be removed.')}</p></div><div class="panel"><h2>${t('الحالة','Status')}</h2><p>${esc(label(STATUS[a.status]||STATUS.pending))}</p><p class="notice">${t('إخفاء الإعلان يزيله من السوق ويحفظ السجلات المرتبطة.','Hiding removes the listing from the market and keeps linked history.')}</p><div class="manage-actions">${a.status==='active'?button(t('إخفاء الإعلان من السوق','Hide from market'),'transition',`data-id="${esc(id)}" data-next="hidden"`):''}${a.status==='hidden'?button(t('إعادة نشر الإعلان','Republish'),'transition',`data-id="${esc(id)}" data-next="active" ${a.moderationLocked?'disabled':''}`):''}${a.status==='active'?button(t('تم البيع','Mark sold'),'transition',`data-id="${esc(id)}" data-next="sold"`):''}${deletionEligibility(a,actor())?button(t('حذف نهائي','Delete permanently'),'transition',`data-id="${esc(id)}" data-next="deleted"`,'danger'):''}</div>${!deletionEligibility(a,actor())?`<p class="muted small">${t('الحذف النهائي غير مؤهل. استخدم الإخفاء لحفظ السجلات.','Permanent deletion is ineligible. Hide to preserve history.')}</p>`:''}</div><div class="panel"><h2>${t('بيانات الإعلان والسعر','Listing details & price')}</h2>${a.legacy?`<p>${esc(a.description)}</p><p class="price">${price(a)}</p>`:`<div class="form-grid">${detailsFields(d)}</div>`}</div><div class="panel"><h2>${t('الموقع','Location')}</h2>${a.legacy?`<p>${esc(a.region)} · ${esc(a.city)}</p>`:`<div class="form-grid">${locationFields(d)}</div>`}</div><div class="panel"><h2>${t('التواصل','Contact')}</h2>${a.legacy?`<p class="notice">${t('لا يوجد رقم منشور دون موافقة صريحة.','No contact number is published without explicit consent.')}</p>`:`<div class="form-grid">${contactFields(d)}</div>`}</div><div class="panel"><h2>${t('خدمات الإعلان','Listing services')}</h2><p class="muted small">${t('الدفع معطل. الطلبات في هذه المعاينة محلية فقط.','Payments disabled. Preview requests are local only.')}</p><div class="chips">${[['featured','تمييز الإعلان','Feature listing'],['bump','رفع الإعلان','Bump listing'],['verification','طلب توثيق','Request verification']].filter(([k])=>k!=='verification'||['cars','livestock'].includes(a.category)).map(([k,ar,en])=>button(t(ar,en),'service',`data-id="${esc(id)}" data-type="${k}" ${a.status!=='active'?'disabled':''}`)).join('')}</div></div></div>${s.error?`<p role="alert" class="error">${esc(s.error)}</p>`:''}<div class="wizard-actions">${link(t('رجوع إلى إعلاناتي','Back to my listings'),'my-listings','button')}${!a.legacy?`<button class="primary" type="submit" ${s.busy?'disabled':''}>${t('حفظ التغييرات','Save changes')}</button>`:''}</div></form>`;}
function adminAllowed(section){if(runtimeConfig.mode==='review'&&section==='legacy')return false;const a=actor();const permission={home:'dashboard_view',users:'users_view',listings:'listings_view',featured:'services_view',reports:'reports_view',assistants:'assistants_view',audit:'admin_log_view'}[section];return ['categories','commercial','analytics','settings','legacy'].includes(section)?a.role==='super_admin':!!permission&&can(a,permission);}
function admin(section='home'){if(!adminAllowed(section))return noData(t('هذه الصفحة غير متاحة لصلاحيتك','This page is unavailable for your permissions'));const menu=[['home','home','الرئيسية','Overview'],['users','user','المستخدمون','Users'],['listings','grid','الإعلانات','Listings'],['categories','grid','الأقسام','Categories'],['featured','shield','الإعلانات المميزة','Featured listings'],['commercial','chart','الإعلانات التجارية','Commercial ads'],['reports','flag','البلاغات','Reports'],['assistants','user','المساعدون والصلاحيات','Assistants & permissions'],['analytics','chart','إحصاءات الزوار','Visitor analytics'],['audit','clock','سجل الإدارة','Audit log'],['settings','tool','الإعدادات','Settings'],['legacy','grid','Legacy Data','Legacy Data']];let content='';const stats=store.statistics(s.adminCountry),rows=store.state.listings.filter(a=>a.saleType!=='auction'&&(!s.adminCountry||a.country===s.adminCountry));const title=menu.find(m=>m[0]===section);const head=`<div class="page-head"><div><small class="muted">${t('مرحبًا بك مجددًا،','Welcome back,')} ${actor().name}</small><h1>${t(title[2],title[3])}</h1></div><select id="admin-country" aria-label="${t('دولة إحصاءات الإدارة','Dashboard country')}">${countryOptions(s.adminCountry,true)}</select></div>`;
if(section==='home'){const cards=[['total','إجمالي الإعلانات','Total listings','grid'],['active','نشط','Active','check'],['sold','تم البيع','Sold','check'],['hidden','مخفي','Hidden','shield'],['featured','مميز','Featured','shield'],['reports','بلاغات جديدة','New reports','flag'],['users','مستخدمون','Users','user']];content=`<div class="stats">${cards.map(([k,ar,en,i])=>`<a class="stat" href="#/admin/${k==='users'?'users':k==='reports'?'reports':k==='featured'||k==='soon'?'featured':'listings'}" data-stat="${k}"><div><small>${t(ar,en)}</small><strong>${stats[k]}</strong></div>${icon(i)}</a>`).join('')}</div><div class="admin-two"><section class="panel"><h3>${t('الإعلانات حسب القسم','Listings by category')}</h3>${CATEGORIES.map(c=>{const n=rows.filter(a=>a.category===c.id).length;return `<div class="bar-row"><span>${esc(label(c.name))}</span><div class="bar-track"><progress value="${n}" max="${Math.max(1,rows.length)}">${n}</progress></div><b>${n}</b></div>`;}).join('')}</section><section class="panel"><h3>${t('آخر الأنشطة المحلية','Recent local activity')}</h3>${store.state.audit.slice(0,8).map(a=>`<div class="activity">${icon('clock')}<div><strong>${esc(a.action)}</strong><p class="muted">${date(a.at)} · ${esc(a.target)}</p></div></div>`).join('')||`<p class="notice">${t('لا توجد عمليات بعد. ستظهر أفعالك المحلية هنا.','No actions yet. Your local actions will appear here.')}</p>`}</section></div>`;}
if(section==='listings'){const items=rows.filter(a=>!s.adminStatus||a.status===s.adminStatus).slice(0,50);content=`<div class="chips">${button(t('الكل','All'),'admin-filter','data-status=""',!s.adminStatus?'selected':'')}${Object.entries(STATUS).map(([k,v])=>button(label(v),'admin-filter',`data-status="${k}"`,s.adminStatus===k?'selected':'')).join('')}</div>${table([t('الإعلان','Listing'),t('القسم','Category'),t('الحالة','Status'),t('السعر','Price'),t('إجراءات','Actions')],items.map(a=>[`<div><img src="${asset(a.images[0])}" alt=""> ${esc(a.title)}</div>`,esc(label(CATEGORIES.find(c=>c.id===a.category).name)),esc(label(STATUS[a.status]||STATUS.pending)),price(a),link(t('عرض','View'),'listing/'+a.id,'button')+(can(actor(),'listings_manage')&&!a.legacy?button(t('مراجعة','Review'),'moderate',`data-id="${esc(a.id)}"`):'')]))}`;}
if(section==='users')content=table([t('الاسم','Name'),'UID',t('الصلاحية','Role'),t('الحماية','Protection')],store.state.users.filter(u=>!s.adminCountry||u.country===s.adminCountry).map(u=>[esc(u.name),esc(u.uid),u.role==='super_admin'?`${t('مالك المنصة','Platform owner')} — Super Admin`:esc(u.role),u.role==='super_admin'?t('محمي · لا حذف أو تعطيل','Protected · No deletion or suspension'):t('قراءة محلية','Local read-only')]));
if(section==='categories')content=`<p class="notice">${t('إعدادات العرض فقط. مخطط الحقول محفوظ في الإعدادات ولا يمكن تغييره هنا.','Presentation settings only. Sensitive field schemas cannot be edited here.')}</p><div class="admin-categories">${store.state.categories.sort((a,b)=>a.order-b.order).map(c=>`<form class="category-row" data-category-form="${c.id}">${icon(c.icon)}<strong>${esc(label(c.name))}</strong><label><input type="checkbox" name="enabled" ${c.enabled?'checked':''}>${t('مفعّل','Enabled')}</label><label><input type="checkbox" name="featured" ${c.featured?'checked':''}>${t('قسم بارز','Featured category')}</label><label>${t('الترتيب','Order')}<input type="number" name="order" min="0" max="99" value="${c.order}" aria-label="${t('ترتيب','Order')} ${esc(label(c.name))}"></label><label>${t('الأيقونة','Icon')}<select name="icon">${['car','phone','computer','appliance','sofa','tool','bike','baby','grid','camel'].map(k=>option(k,k,c.icon)).join('')}</select></label><button type="submit" class="primary">${t('حفظ','Save')}</button></form>`).join('')}</div>`;
if(section==='featured')content=v.featuredManagement(rows);
if(section==='commercial')content=v.commercialMap();
if(section==='reports')content=v.reports();
if(section==='assistants')content=`<div class="panel"><h2>${t('المساعدون والصلاحيات','Assistants & permissions')}</h2><p class="notice">${t('آلية الصلاحيات الحالية محفوظة. لا يمكن منح Super Admin من صفحة المعاينة.','Existing permission policy preserved. Super Admin cannot be granted from this preview.')}</p>${table([t('المساعد','Assistant'),t('الصلاحيات','Permissions')],[[t('مساعد تجريبي','Demo assistant'),'dashboard_view · listings_view · reports_view']])}</div>`;
if(section==='analytics')content=`<div class="panel"><h2>${t('جمع الإحصاءات غير مفعّل حاليًا','Analytics collection is currently disabled')}</h2><p class="notice">${t('لا جلسات مسجلة ولا أرقام زوار وهمية. لا تغيير في Feature Flag.','No sessions recorded and no invented visitor counts. The feature flag is unchanged.')}</p></div>`;
if(section==='audit')content=table([t('الفاعل','Actor'),t('العملية','Action'),t('المعرف','Target'),t('السبب','Reason'),t('الوقت','Time'),t('النتيجة','Result')],store.state.audit.map(a=>[esc(a.actor),esc(a.action),esc(a.targetId||a.target),esc(a.reason||''),date(a.timestamp||a.at),esc(a.result||'success')]));
if(section==='settings')content=`<div class="panel"><h2>MELKAK</h2><p>${t('بيع واشتري مباشرة','Buy and sell directly')}</p><p class="notice">${t('الدفع والإحصاءات والكتابة إلى Production معطّلة. الدول والأقسام من إعدادات قابلة للتوسع.','Payments, analytics and Production writes are disabled. Countries and categories are configuration driven.')}</p></div>`;
if(section==='legacy')content=`<p class="notice">${t('للمالك فقط · قراءة محاكاة للسجلات القديمة · لا حذف أو تغيير.','Owner only · Read-only legacy fixtures · No deletion or editing.')}</p>${['auctions','purchaseRequests','conversations','messages'].map(k=>`<section class="panel"><h3>${esc(k)}</h3>${table(['ID',t('الحالة','Status')],store.legacyRead(k,actor()).map(x=>[esc(x.id),esc(x.status)]))}</section>`).join('')}`;
return `<div class="admin-layout"><aside class="admin-sidebar" id="admin-navigation">${brand()}<nav aria-label="${t('أقسام الإدارة','Admin sections')}">${menu.filter(([k])=>adminAllowed(k)).map(([k,i,ar,en])=>link(icon(i)+t(ar,en),'admin/'+k,'nav-item '+(section===k?'active':''))).join('')}</nav></aside><div class="admin-main">${button(icon('grid')+t('قائمة الإدارة','Admin menu'),'admin-drawer','aria-haspopup="dialog"','admin-menu-toggle')}${head}${content}</div></div>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c??'—'}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">${t('لا توجد بيانات محلية بعد','No local data yet')}</td></tr>`}</tbody></table></div>`;}
function settings(kind){const title={profile:['ملفي','Profile'],'contact-settings':['بيانات التواصل','Contact details'],'location-settings':['الدولة والمدينة','Location'],settings:['الإعدادات','Settings']}[kind];return `<div class="page-head"><h1>${esc(label(title))}</h1></div><div class="panel">${kind==='profile'?`<h2>${actor().name}</h2><p class="notice">${t('الملف الحقيقي وGoogle Auth محفوظان دون تعديل. بيانات هذه الجلسة تجريبية.','Real profiles and Google Auth remain unchanged. This session uses local demo data.')}</p>`:kind==='contact-settings'?`<p class="notice">${t('رقم التواصل يضاف لكل إعلان بموافقة مستقلة. لا ننسخ رقم الحساب علنًا.','Contact numbers are entered per listing with independent consent. We never publish your profile number automatically.')}</p>${link(t('أضف إعلانًا مع بيانات التواصل','Create a listing with contact details'),'add','button')}`:kind==='location-settings'?`<form id="location-form" class="form-grid"><label>${t('الدولة','Country')}<select data-country>${countryOptions(s.country)}</select></label><label>${t('المدينة','City')}<select data-city>${cityOptions(s.country,s.city)}</select></label></form>`:`<div class="chips">${button(t('التبديل إلى English','Switch to العربية'),'language')}${button(t('مسح مفضلات المعاينة','Clear preview favorites'),'clear-favorites')}</div>`}</div>`;}
function route(){return (location.hash.replace(/^#\/?/,'')||'home').split('/');}
function render(){document.documentElement.lang=s.lang;document.documentElement.dir=s.lang==='ar'?'rtl':'ltr';document.title=t('مِلكك | بيع واشتري مباشرة','MELKAK | Buy and sell directly');const [r,id]=route();let content='';if(r==='home')content=v.home();else if(r==='commercial-request')content=v.requestCommercial();else if(['about','contact','privacy','terms'].includes(r))content=v.info(r);else if(r==='featured')content=`<div class="page-head"><h1>${t('الإعلانات المميزة','Featured listings')}</h1></div>${cards(publicRows().filter(a=>featured(a)&&a.country===s.country))}`;else if(r==='categories')content=`<div class="page-head"><h1>${t('كل الأقسام. فرص بلا حدود.','Every category. Endless possibilities.')}</h1></div>${categories(true)}<p class="notice">${t('العقارات والوظائف والخدمات ليست ضمن هذه المرحلة.','Real estate, jobs and services are outside this phase.')}</p>`;else if(r==='market')content=market(id);else if(r==='listing')content=details(id);else if(r==='add')content=addListing();else if(r==='account')content=account();else if(r==='favorites')content=`<div class="page-head"><h1>${t('المفضلة','Favorites')}</h1><small>${t('محفوظة على هذا الجهاز لكل جلسة محلية','Saved on this device per local user')}</small></div>${cards(store.state.listings.filter(a=>s.favorites.has(a.id)&&a.status==='active'&&a.saleType!=='auction'))}`;else if(r==='my-listings')content=myListings();else if(r==='manage')content=manage(id);else if(r==='admin')content=admin(id||'home');else if(['profile','contact-settings','location-settings','settings'].includes(r))content=settings(r);else content=noData(t('الصفحة غير موجودة','Page not found'));$('#app').innerHTML=shell(content,r);document.dispatchEvent(new Event('melkak-rendered'));}
function openDialog(title,body){const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${button('×','close-dialog',`aria-label="${t('إغلاق','Close')}"`,'icon-button')}</div>${body}`;d.showModal();d.querySelector('input,textarea,button')?.focus();}
function collect(form){const d=s.draft;if(!d)return;for(const [k,v]of new FormData(form)){if(k.startsWith('attr:'))d.attributes[k.slice(5)]=String(v);else if(['title','description','price','region','city'].includes(k))d[k]=k==='price'?Number(v):v;else if(k==='phone')d.contact.phone=v;}
for(const k of ['call','whatsapp','showNumber','consent'])if(form.elements[k])d.contact[k]=form.elements[k].checked;}
async function imageFiles(files){try{const form=$('#wizard-form')||$('#manage-form');if(form)collect(form);const list=Array.from(files||[]);if(!list.length)return;if((s.replaceIndex==null?s.draft.images.length:0)+list.length>3||(s.replaceIndex!=null&&list.length!==1))throw Error('TOO_MANY_IMAGES');s.busy=true;s.error='';render();const data=await listingImageData(list,{uid:actor().uid});const next=[...s.draft.images];if(s.replaceIndex!=null)next[s.replaceIndex]=data[0];else next.push(...data);if(new Set(next).size!==next.length)throw Error('IMAGES');s.draft.images=next;}catch(e){s.error=errorText(e);}finally{s.busy=false;s.replaceIndex=null;render();}}
window.addEventListener('hashchange',()=>{s.page=1;s.error='';s.editing=null;if(route()[0]==='add'){s.draft=newDraft();s.step=0;}render();window.scrollTo(0,0);$('#main')?.focus({preventScroll:true});});
document.addEventListener('click',async e=>{const contact=e.target.closest('[data-contact]');if(contact){const a=store.state.listings.find(a=>a.id===contact.dataset.id);if(a?.demo){e.preventDefault();toast(t('رابط تواصل تجريبي — لم يُجرَ اتصال فعلي.','Demo contact link — no real call was made.'));}return;}const stat=e.target.closest('[data-stat]');if(stat)s.adminStatus=['active','hidden','sold','rejected'].includes(stat.dataset.stat)?stat.dataset.stat:'';const el=e.target.closest('[data-action]');if(!el)return;const {action,id,index,next,type,status}=el.dataset;try{
if(action==='language'){s.lang=s.lang==='ar'?'en':'ar';localStorage.setItem('melkak.lang',s.lang);render();}
else if(action==='hero-next'||action==='hero-prev'){const n=countryAds(store.state.ads,'hero',s.country,Date.now(),s.city).length||1;s.hero=(s.hero+(action==='hero-next'?1:n-1))%n;render();}
else if(action==='favorite'){s.favorites.has(id)?s.favorites.delete(id):s.favorites.add(id);localStorage.setItem('melkak.favorites.'+actor().uid,JSON.stringify([...s.favorites]));render();}
else if(action==='clear-favorites'){s.favorites.clear();localStorage.removeItem('melkak.favorites.'+actor().uid);render();}
else if(action==='clear-filters'){Object.assign(s,{search:'',min:'',max:'',city:'',attributes:{},page:1});render();}
else if(action==='page-next'||action==='page-prev'){s.page=Math.max(1,s.page+(action==='page-next'?1:-1));render();window.scrollTo(0,0);}
else if(action==='gallery'){s.gallery[id]=Number(index);render();}
else if(action==='wizard-back'){collect($('#wizard-form'));s.step=Math.max(0,s.step-1);s.error='';render();}
else if(action==='image-add'){if(s.busy||s.draft.images.length>=3)return;s.replaceIndex=null;$('#photo-picker').multiple=true;$('#photo-picker').click();}
else if(action.startsWith('image-')){collect($('#wizard-form')||$('#manage-form'));const i=Number(index);if(action==='image-replace'){s.replaceIndex=i;$('#photo-picker').multiple=false;$('#photo-picker').click();return;}if(action==='image-remove'){const a=store.state.listings.find(x=>x.id===s.editing);if(a?.status==='active'&&s.draft.images.length===1)throw Error('IMAGES');s.draft.images.splice(i,1);}if(action==='image-main'){s.draft.images.unshift(s.draft.images.splice(i,1)[0]);}if(action==='image-up'&&i>0)[s.draft.images[i-1],s.draft.images[i]]=[s.draft.images[i],s.draft.images[i-1]];render();}
else if(action==='my-filter'){s.myStatus=status;s.page=1;render();}else if(action==='admin-filter'){s.adminStatus=status;render();}
else if(action==='transition'){openDialog(t('تأكيد الإجراء المحلي','Confirm local action'),`<p>${t('سيؤثر هذا الإجراء على بيانات المعاينة المحلية فقط.','This action affects only local preview data.')}</p><form id="transition-form" data-id="${esc(id)}" data-next="${esc(next)}"><button class="${next==='deleted'?'danger':'primary'}" type="submit">${t('تأكيد','Confirm')}</button></form>`);}
else if(action==='service'){v.serviceDialog(id,type);}
else if(action==='report'){openDialog(t('الإبلاغ عن الإعلان','Report listing'),`<form id="report-form" data-id="${esc(id)}"><label>${t('سبب البلاغ','Reason')}<textarea name="reason" required maxlength="500"></textarea></label><button class="danger" type="submit">${t('إرسال البلاغ محليًا','Submit locally')}</button></form>`);}
else if(action==='approve-service'){openDialog(t('اعتماد استثنائي بدون دفع','Exceptional approval without payment'),`<form id="approve-form" data-id="${esc(id)}"><label>${t('سبب الاعتماد','Approval reason')}<textarea name="reason" required maxlength="500"></textarea></label><button class="gold" type="submit">${t('اعتماد محلي','Approve locally')}</button></form>`);}
else if(action==='resolve-report'){store.resolveReport(id,actor());render();}
else if(action==='notifications'){openDialog(t('الإشعارات','Notifications'),`${notifications().map(n=>`<div class="activity">${icon('bell')}<div>${link(esc(n.text),'admin/'+n.section)} ${s.unread.has(n.id)?t('مقروء','Read'):button(t('تعليم كمقروء','Mark read'),'notification-read',`data-id="${n.id}"`)}</div></div>`).join('')||`<p>${t('لا توجد إشعارات متاحة لهذه الصلاحية','No notifications available for this role')}</p>`}${button(t('تعليم الكل كمقروء','Mark all read'),'notifications-all')}`);}
else if(action==='notification-read'||action==='notifications-all'){for(const n of notifications())if(action==='notifications-all'||n.id===id)s.unread.add(n.id);localStorage.setItem('melkak.read.'+actor().uid,JSON.stringify([...s.unread]));$('#dialog').close();render();}
else if(action==='close-dialog')$('#dialog').close();
else if(action==='preview-login'){s.signedIn=true;s.role='user';favoritesLoad();render();}
else if(action==='logout'){s.signedIn=false;s.role='user';favoritesLoad();location.hash='#/account';render();toast(t('انتهت جلسة الإدارة المحلية؛ لا تغيير في جلسة Google الحقيقية.','Local admin preview ended; real Google sessions unchanged.'));}
else if(action==='moderate'){openDialog(t('مراجعة الإعلان','Review listing'),`<form id="moderate-form" data-id="${esc(id)}"><label>${t('الحالة','Status')}<select name="status">${['active','hidden','rejected','archived'].map(k=>option(k,label(STATUS[k]),'hidden')).join('')}</select></label><label>${t('السبب','Reason')}<textarea required maxlength="500" name="reason"></textarea></label><button class="primary" type="submit">${t('حفظ محلي','Save locally')}</button></form>`);}
}catch(err){toast(errorText(err));}});
document.addEventListener('change',e=>{const el=e.target;try{if(el.matches('#search-form [name=country]')){s.country=el.value;s.city='';render();}else if(el.matches('[data-country]')){s.country=el.value;s.city='';s.page=1;render();}else if(el.matches('[data-city]')){s.city=el.value;s.page=1;render();}else if(el.id==='preview-role'){s.role=el.value;s.signedIn=true;favoritesLoad();try{s.unread=new Set(JSON.parse(localStorage.getItem('melkak.read.'+actor().uid)||'[]'));}catch{s.unread=new Set();}render();}else if(el.id==='admin-country'){s.adminCountry=el.value;s.commercialPage=1;render();}else if(el.id==='photo-picker')imageFiles(el.files);else if(el.matches('[data-draft-country],[data-draft-region],[data-draft-category]')){collect(el.form);if(el.hasAttribute('data-draft-country')){s.draft.country=el.value;s.draft.region=Object.keys(countries[el.value].regions)[0];s.draft.city=countries[el.value].regions[s.draft.region][0];}else if(el.hasAttribute('data-draft-region')){s.draft.region=el.value;s.draft.city=countries[s.draft.country].regions[el.value][0];}else{s.draft.category=el.value;s.draft.attributes={};}render();}}catch(err){toast(errorText(err));}});
document.addEventListener('cancel',e=>{if(e.target.id==='photo-picker')s.replaceIndex=null;},true);
document.addEventListener('dragover',e=>{if(e.target.closest('#drop-zone'))e.preventDefault();});document.addEventListener('drop',e=>{if(e.target.closest('#drop-zone')){e.preventDefault();imageFiles(e.dataTransfer.files);}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,fd=new FormData(form);try{
if(form.id==='search-form'){s.country=String(fd.get('country')||s.country);s.city=String(fd.get('city')||'');s.search=String(fd.get('search')||'');s.category=String(fd.get('category')||'');s.page=1;const hash='#/market'+(s.category?'/'+s.category:'');if(location.hash===hash)render();else location.hash=hash;}
else if(form.id==='filters-form'){s.city=String(fd.get('city')||'');s.min=fd.get('min');s.max=fd.get('max');s.sort=String(fd.get('sort'));s.attributes=Object.fromEntries([...fd].filter(([k])=>k.startsWith('attr:')).map(([k,v])=>[k.slice(5),v]));s.page=1;render();}
else if(form.id==='wizard-form'){collect(form);const d=s.draft;if(s.step===3&&(d.images.length<1||d.images.length>3))throw Error('IMAGES');if(s.step===4&&(d.title.trim().length<3||d.description.trim().length<10||!Number.isFinite(Number(d.price))||Number(d.price)<0))throw Error('DETAILS');if(s.step===5&&(!d.contact.consent||(!d.contact.call&&!d.contact.whatsapp)||!phoneNumber(d.contact.phone,d.country,countries)))throw Error('CONSENT');if(s.step===6){const a=store.create(d,actor());s.draft=null;s.editing=null;location.hash='#/manage/'+a.id;toast(t('تم نشر الإعلان في المعاينة المحلية فقط','Published only in local preview'));}else{s.step++;s.error='';render();}}
else if(form.id==='manage-form'){collect(form);const d=s.draft;store.update(form.dataset.id,Object.fromEntries(['title','price','description','country','region','city','contact','attributes','images'].map(k=>[k,d[k]])),actor());s.editing=null;s.error='';render();toast(t('حُفظت التغييرات محليًا','Changes saved locally'));}
else if(form.dataset.categoryForm){store.configureCategory(form.dataset.categoryForm,{enabled:form.elements.enabled.checked,featured:form.elements.featured.checked,order:Number(fd.get('order')),icon:String(fd.get('icon'))},actor());render();toast(t('تم حفظ إعدادات العرض','Display settings saved'));}
else if(form.id==='transition-form'){store.transition(form.dataset.id,form.dataset.next,actor());$('#dialog').close();s.editing=null;if(form.dataset.next==='deleted')location.hash='#/my-listings';else render();}
else if(form.id==='report-form'){store.report(form.dataset.id,String(fd.get('reason')),actor());$('#dialog').close();render();toast(t('تم إرسال البلاغ محليًا','Report submitted locally'));}
else if(form.id==='approve-form'){store.approveService(form.dataset.id,String(fd.get('reason')),actor());$('#dialog').close();render();}
else if(form.id==='moderate-form'){store.moderate(form.dataset.id,String(fd.get('status')),String(fd.get('reason')),actor());$('#dialog').close();render();}
}catch(err){if(form.closest('dialog')){toast(errorText(err));}else{s.error=errorText(err);render();}}});
$('#dialog').addEventListener('click',e=>{if(e.target.closest('a[href^="#/"]'))$('#dialog').close();});
const v=phase1Views({s,store,countries,t,esc,icon,link,button,cards,categories,searchbar,actor,can,date,render,openDialog,toast,listingImageData,asset,pageListings,publicRows,featured,noData,previewLogin,errorText});v.bind();installVisualPolish({s,t,countries,render,openDialog,countryOptions,cityOptions,categoryOptions});
window.__melkak=Object.freeze({store,state:s,actor,countries,flags:FLAGS,render});render();
